SELECT n.name, mi1.info, MIN(non_leaf_761.t_production_year), MAX(non_leaf_761.t_production_year)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, non_leaf_761
WHERE (rt.role IN ('actor','actress','cinematographer','composer','costume designer')) AND (it1.id IN ('6','8')) AND (n.name ILIKE '%ashl%') AND (kt.kind IN ('tv series','video game','video movie')) AND (mi1.info IN ('Dolby Digital','Stereo','UK','USA'));